    'formatDate(iso) turns an ISO timestamp into "DD/MM/YYYY" using UTC, so the result never depends on the machine''s time zone. For example "2024-03-05T23:30:00Z" becomes "05/03/2024". formatTimeline(list) formats a list of timestamps, oldest first.',
    '// Formats an ISO timestamp as "DD/MM/YYYY" in UTC, e.g.
// "2024-03-05T23:30:00Z" -> "05/03/2024". UTC keeps the result the same on
// every machine, whatever its time zone.
function formatDate(iso) {
  const date = new Date(iso);
  const day = String(date.getUTCDate());
  const month = String(date.getUTCMonth()).padStart(2, "0");
  const year = date.getUTCFullYear();
  return `${day}/${month}/${year}`;
}

// Formats a list of ISO timestamps, oldest first. Does not change the list.
function formatTimeline(isoList) {
  return [...isoList]
    .sort((a, b) => new Date(a) - new Date(b))
    .map((iso) => formatDate(iso));
}
