    'retry-until-success',
    'javascript',
    'medium',
    'Retry until success',
    'retry(task, options) calls the async task until it succeeds, at most `attempts` times, waiting `delayMs` between tries and calling onRetry(error, attempt) before each retry. It resolves with the first success or rejects with the last error.',
    '// Waits `ms` milliseconds.
function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Calls `task(attempt)` until it succeeds, at most `attempts` times in total,
// waiting `delayMs` between tries. Calls `onRetry(error, attempt)` after each
// failed try that will be retried. Resolves with the first successful result,
// or rejects with the last error when every try fails.
async function retry(task, { attempts = 3, delayMs = 0, onRetry } = {}) {
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return task(attempt);
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        if (onRetry) onRetry(error, attempt);
        await wait(delayMs);
      }
    }
  }
  throw lastError;
}
',
    'function flaky(failures) {
  let calls = 0;
  return async (attempt) => {
    calls += 1;
    if (calls <= failures) throw new Error(`fail ${attempt}`);
    return `ok on ${attempt}`;
  };
}

async function errorFrom(promise) {
  try {
    await promise;
  } catch (error) {
    return error.message;
  }
  return "no error";
}

test("resolves on the first try", async () => {
  expect(await retry(flaky(0))).toBe("ok on 1");
});
test("retries a rejected task", async () => {
  expect(await retry(flaky(2), { attempts: 3 })).toBe("ok on 3");
});
test("rejects with the last error", async () => {
  expect(await errorFrom(retry(flaky(5), { attempts: 3 }))).toBe("fail 3");
});
test("reports each retry", async () => {
  const seen = [];
  await retry(flaky(2), {
    onRetry: (error, n) => seen.push([error.message, n]),
  });
  expect(seen).toEqual([
    ["fail 1", 1],
    ["fail 2", 2],
  ]);
});
test("retries a task that throws synchronously", async () => {
  let calls = 0;
  const task = () => {
    calls += 1;
    if (calls === 1) throw new Error("sync");
    return "done";
  };
  expect(await retry(task)).toBe("done");
});
