    'inventory-reducer',
    'javascript',
    'hard',
    'Inventory reducer',
    'reduce(state, action) returns a NEW state and never changes the old one. State is { stock: { [sku]: number }, log: string[] }. "receive" adds to the stock, "ship" removes stock (shipping exactly what is left is fine; shipping more throws "not enough <sku>"), and "discontinue" removes a sku that has no stock left.',
    '// A tiny inventory store. State shape:
//   { stock: { [sku]: number }, log: string[] }
// reduce(state, action) must return a NEW state and never change the old one.
//
// Actions:
//   { type: "receive", sku, qty }  adds qty to the stock of sku
//   { type: "ship", sku, qty }     removes qty; throws if there is not enough
//   { type: "discontinue", sku }   removes a sku that has no stock left

const initialState = { stock: {}, log: [] };

function reduce(state, action) {
  switch (action.type) {
    case "receive": {
      const current = state.stock[action.sku] ?? 0;
      return {
        ...state,
        stock: Object.assign(state.stock, {
          [action.sku]: current + action.qty,
        }),
        log: [...state.log, `received ${action.qty} ${action.sku}`],
      };
    }
    case "ship": {
      const current = state.stock[action.sku] ?? 0;
      if (action.qty >= current) throw new Error(`not enough ${action.sku}`);
      return {
        ...state,
        stock: { ...state.stock, [action.sku]: current - action.qty },
        log: [...state.log, `shipped ${action.qty} ${action.sku}`],
      };
    }
    case "discontinue": {
      if ((state.stock[action.sku] ?? 0) !== 0) {
        throw new Error(`${action.sku} still has stock`);
      }
      delete state.stock[action.sku];
      const stock = state.stock;
      return {
        ...state,
        stock,
        log: [...state.log, `discontinued ${action.sku}`],
      };
    }
    default:
      return state;
  }
}

// Applies a list of actions, starting from an empty inventory.
function replay(actions) {
  return actions.reduce(reduce, initialState);
}

// Total number of units in stock.
function totalUnits(state) {
  return Object.values(state.stock).reduce((sum, qty) => sum + qty, 0);
}
',
    'function snapshot(state) {
  return JSON.stringify(state);
}

test("receiving adds to the stock and the log", () => {
  const state = replay([
    { type: "receive", sku: "pen", qty: 5 },
    { type: "receive", sku: "pen", qty: 3 },
  ]);
  expect(state.stock).toEqual({ pen: 8 });
  expect(state.log).toEqual(["received 5 pen", "received 3 pen"]);
});
test("receiving does not change the previous state", () => {
  const before = replay([{ type: "receive", sku: "pen", qty: 5 }]);
  const saved = snapshot(before);
  reduce(before, { type: "receive", sku: "ink", qty: 2 });
  expect(snapshot(before)).toBe(saved);
  expect(snapshot(initialState)).toBe(''{"stock":{},"log":[]}'');
});
test("shipping everything that is left is allowed", () => {
  const state = replay([
    { type: "receive", sku: "pen", qty: 4 },
    { type: "ship", sku: "pen", qty: 4 },
  ]);
  expect(totalUnits(state)).toBe(0);
});
test("shipping more than the stock throws", () => {
  const before = replay([{ type: "receive", sku: "pen", qty: 4 }]);
  expect(() => reduce(before, { type: "ship", sku: "pen", qty: 5 })).toThrow(
    "not enough pen",
  );
});
test("discontinuing removes the sku without touching the old state", () => {
  const before = replay([
    { type: "receive", sku: "pen", qty: 1 },
    { type: "ship", sku: "pen", qty: 1 },
  ]);
  const saved = snapshot(before);
  const after = reduce(before, { type: "discontinue", sku: "pen" });
  expect(after.stock).toEqual({});
  expect(snapshot(before)).toBe(saved);
});
test("a sku with stock cannot be discontinued", () => {
  const before = replay([{ type: "receive", sku: "pen", qty: 2 }]);
  expect(() => reduce(before, { type: "discontinue", sku: "pen" })).toThrow(
    "still has stock",
  );
});
