    'async-batches',
    'typescript',
    'hard',
    'Run in batches',
    'mapInBatches(items, batchSize, worker) runs the worker on the items one batch at a time: the items of a batch run together, and the next batch starts only when the previous one is done. Results come back in the same order as the items, and onProgress(done, total) is called after every batch. settleInBatches never rejects: every item becomes { ok: true, value } or { ok: false, error } where error is the error''s message.',
    'type Progress = (done: number, total: number) => void;

// Runs `worker` over `items` in batches: the items of one batch run at the same
// time, and the next batch starts only after the previous one has finished (so
// at most `batchSize` jobs run at once). Results keep the order of `items`.
// If a worker rejects, the returned promise rejects with that error.
// `onProgress(done, total)` is called after every batch.
async function mapInBatches<T, R>(
  items: T[],
  batchSize: number,
  worker: (item: T) => Promise<R>,
  onProgress?: Progress,
): Promise<R[]> {
  if (batchSize < 1) throw new Error("batchSize must be at least 1");
  const results: R[] = [];
  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize - 1);
    const done = Promise.all(batch.map((item) => worker(item)));
    results.push(...done);
    onProgress?.(i + 1, items.length);
  }
  return results;
}

type Outcome<R> = { ok: true; value: R } | { ok: false; error: string };

// Like mapInBatches, but never rejects: every item gets an outcome, in order.
// `error` is the message of the thrown Error.
async function settleInBatches<T, R>(
  items: T[],
  batchSize: number,
  worker: (item: T) => Promise<R>,
): Promise<Outcome<R>[]> {
  return mapInBatches(items, batchSize, async (item): Promise<Outcome<R>> => {
    try {
      return { ok: true, value: await worker(item) };
    } catch (error) {
      return {
        ok: false,
        error: error instanceof Error ? error.message : String(error),
      };
    }
  });
}

// How many batches mapInBatches needs for `total` items.
function batchCount(total: number, batchSize: number): number {
  return Math.ceil(total / batchSize);
}
',
    'function later<T>(value: T, ms: number): Promise<T> {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

test("keeps the order of the items", async () => {
  const delays: Record<number, number> = { 1: 15, 2: 1, 3: 8 };
  const result = await mapInBatches([1, 2, 3], 3, (n) =>
    later(n * 10, delays[n]),
  );
  expect(result).toEqual([10, 20, 30]);
});
test("every item is processed, including the last of each batch", async () => {
  const seen: number[] = [];
  await mapInBatches([1, 2, 3, 4, 5], 2, async (n) => {
    seen.push(n);
    return n;
  });
