  bus.on("ping", recorder(log, "a"));
  bus.on("ping", recorder(log, "b"));
  expect(bus.emit("ping", "x")).toBe(2);
  expect(log).toEqual(["a:x", "b:x"]);
});
test("an unsubscribed handler is not called again", () => {
